def transform_shift_base(grid):
    """Shift non-zero by (+4,+4), then apply: original 5s stay if not shifted, non-5 reload"""
    h = len(grid)
    w = len(grid[0])
    result = [[0]*w for _ in range(h)]

    # Step 1: All non-zero shifted by (+4,+4)
    shift_r, shift_c = 4, 4
    shifts = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                nr, nc = r + shift_r, c + shift_c
                if 0 <= nr < h and 0 <= nc < w:
                    shifts.append(((nr, nc), v))

    # Apply shifts
    for ((nr, nc), v) in shifts:
        result[nr][nc] = v

    # Step 2: Restore original 5s (they stay wherever they are)
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 5:
                result[r][c] = 5

    # Step 3: Reload original non-5 non-zero values
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != 5:
                result[r][c] = v

    return result

