def transform_dynamic_shift(grid):
    """Shift non-5 values by amount equal to 5s displacement"""
    h = len(grid)
    w = len(grid[0])

    # Find all 5 positions
    fives = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(fives) < 2:
        return grid  # No shift if less than 2 5s

    # Calculate shift from first 5 to second 5
    dr = (fives[1][0] - fives[0][0]) % h
    dc = (fives[1][1] - fives[0][1]) % w

    # Shift all non-5 non-zero values
    result = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 5 and v != 0:
                tr, tc = (r + dr) % h, (c + dc) % w
                result[tr][tc] = v

    # Add original 5s
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                result[r][c] = 5

    return result

